import * as THREE from './vendor/three.module.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {describe,hraNames} from './atlas-data.js';
const $=id=>document.getElementById(id),view=$('viewport');
let renderer,scene,camera,controls,root,items=[],selected=null,isolated=false,mode='internal',loadToken=0,cutPlane=new THREE.Plane(new THREE.Vector3(0,0,-1),0),referenceCenter=new THREE.Vector3(),scale=1;
const linkParams=new URLSearchParams(location.search);let linkApplied=false;const cache={},ray=new THREE.Raycaster(),pointer=new THREE.Vector2(),temp=new THREE.Vector3();
function colour(name){const group=describe(name)[0];if(/valve/i.test(name))return '#e8cb87';if(/papillary/i.test(name))return '#c398bc';if(/septum/i.test(name))return '#ddac96';if(group==='Chambers')return /right/i.test(name)?'#7fa8be':'#d98675';if(/arter|aorta/i.test(name)&&!(/pulmonary/i.test(name)))return '#d87360';if(/pulmonary.*vein/i.test(name))return '#d87360';if(/vein|vena|sinus|pulmonary/i.test(name))return '#789fc4';return '#bb7c75'}
function setup(){renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x172621,0);renderer.localClippingEnabled=true;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.4;view.prepend(renderer.domElement);scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(35,1,.01,100);camera.position.set(0,.4,7);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.08;controls.minDistance=.65;controls.maxDistance=16;controls.autoRotateSpeed=.65;scene.add(new THREE.HemisphereLight(0xe5f0dd,0x343326,2.5));const key=new THREE.DirectionalLight(0xffeee0,3.3);key.position.set(-3,5,7);scene.add(key);const fill=new THREE.DirectionalLight(0xc5deff,1.9);fill.position.set(5,0,-3);scene.add(fill);const rim=new THREE.DirectionalLight(0xffead2,2);rim.position.set(-4,1,-4);scene.add(rim);const resize=()=>{const w=view.clientWidth,h=view.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()};new ResizeObserver(resize).observe(view);resize();let down=null;renderer.domElement.addEventListener('pointerdown',e=>down={x:e.clientX,y:e.clientY});renderer.domElement.addEventListener('pointerup',e=>{if(!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>6)return;const rect=view.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(pointer,camera);const hits=ray.intersectObjects(items.flatMap(i=>i.meshes).filter(m=>m.visible),false).filter(h=>!$('cut').checked||cutPlane.distanceToPoint(h.point)>=0);if(hits[0])choose(hits[0].object.userData.item)});renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('load').hidden=false;$('load').textContent='3D graphics were interrupted. Reload this page to restore the model.'});function frame(){requestAnimationFrame(frame);controls.update();if(selected&&!$('pin').hidden){const box=new THREE.Box3();selected.meshes.filter(m=>m.visible).forEach(m=>box.expandByObject(m));if(!box.isEmpty()){box.getCenter(temp);temp.project(camera);$('pin').style.left=(temp.x*.5+.5)*view.clientWidth+'px';$('pin').style.top=(-temp.y*.5+.5)*view.clientHeight+'px';$('pin').style.visibility=Math.abs(temp.x)>1||Math.abs(temp.y)>1||temp.z>1?'hidden':'visible'}}renderer.render(scene,camera)}frame()}
function makeItem(name,meshes){const item={name,meshes,group:describe(name)[0],colour:colour(name)};for(const m of meshes){m.material=new THREE.MeshStandardMaterial({color:item.colour,roughness:.48,metalness:0,side:THREE.DoubleSide});m.userData.item=item;m.userData.base=m.position.clone();m.geometry.computeBoundingBox();m.geometry.boundingBox.getCenter(temp);m.userData.center=temp.clone();}return item}
async function heart(){const gltf=await new GLTFLoader().loadAsync('./models/heart.glb');const list=[];gltf.scene.traverse(m=>{if(m.isMesh)list.push(makeItem(hraNames[m.name]||m.name,[m]))});return {root:gltf.scene,items:list}}
function vascularName(n){if(/wall of/i.test(n))return 'Heart wall';if(/cavity of/i.test(n))return n.replace('Cavity of ','').replace(/^./,x=>x.toUpperCase());if(/diagonal branch/i.test(n))return 'Diagonal branches (LAD)';if(/circumflex/i.test(n))return 'Circumflex coronary artery';if(/posterior interventricular/i.test(n))return 'Posterior interventricular coronary artery';if(/anterior interventricular/i.test(n))return 'Anterior interventricular coronary artery (LAD)';if(/marginal branch of right/i.test(n))return 'Right marginal coronary branches';if(/ventricular branch of right/i.test(n))return 'Right ventricular coronary branches';if(/trunk of right coronary/i.test(n))return 'Right coronary artery';if(/trunk of left coronary/i.test(n))return 'Left coronary artery';if(/posterior vein of left ventricle/i.test(n))return 'Posterior veins of left ventricle';return n}
async function vessels(){const [meta,buffer]=await Promise.all([fetch('./models/vessels.json').then(r=>{if(!r.ok)throw Error('Vessel index unavailable');return r.json()}),fetch('./models/vessels.bin').then(r=>{if(!r.ok)throw Error('Vessel model unavailable');return r.arrayBuffer()})]);const group=new THREE.Group(),map=new Map();for(const p of meta){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(buffer,p.positions,p.vertexCount*3),3));g.setAttribute('normal',new THREE.BufferAttribute(new Int16Array(buffer,p.normals,p.vertexCount*3),3,true));g.setIndex(new THREE.BufferAttribute(new Uint32Array(buffer,p.indices,p.indexCount),1));const m=new THREE.Mesh(g);group.add(m);const name=vascularName(p.name);if(!map.has(name))map.set(name,[]);map.get(name).push(m)}return {root:group,items:[...map].map(([n,m])=>makeItem(n,m))}}
async function layers(){const group=new THREE.Group(),list=[],defs=[['Endocardium',.10,'#e9c4b0'],['Myocardium',.60,'#b65e59'],['Epicardium',.09,'#dec78e'],['Pericardial cavity',.15,'#9bbfc0'],['Pericardial sac',.15,'#c9cdb2']];let z=-.7;for(const [name,depth,c] of defs){const mesh=new THREE.Mesh(new THREE.BoxGeometry(1.75,1.5,depth,1,1,1));mesh.position.z=z+depth/2;z+=depth+.08;group.add(mesh);const item=makeItem(name,[mesh]);item.colour=c;mesh.material.color.set(c);list.push(item)}return {root:group,items:list}}
function setHome(){controls.target.set(0,0,0);camera.position.set(mode==='layers'?3:0,mode==='layers'?2:.45,mode==='layers'?5:7);controls.update()}
async function loadModel(next){const token=++loadToken;mode=next;controls.autoRotate=false;$('rotate').classList.remove('active');$('rotate').setAttribute('aria-pressed','false');selected=null;isolated=false;$('pin').hidden=true;$('details').hidden=true;$('instruction').hidden=false;$('name').textContent='Choose a structure.';$('category').textContent='EXPLORE THE MODEL';$('search').value='';$('load').hidden=false;$('load').textContent='Loading anatomical model…';$('structurelist').innerHTML='';$('count').textContent='—';if(root){scene.remove(root);root=null}items=[];document.querySelectorAll('[data-model]').forEach(b=>{b.classList.toggle('active',b.dataset.model===mode);b.setAttribute('aria-pressed',String(b.dataset.model===mode))});try{if(!cache[mode])cache[mode]=(mode==='internal'?heart:mode==='vascular'?vessels:layers)();const data=await cache[mode];if(token!==loadToken)return;root=data.root;items=data.items;root.position.set(0,0,0);root.scale.setScalar(1);items.forEach(i=>i.meshes.forEach(m=>{m.position.copy(m.userData.base);m.visible=true}));root.updateMatrixWorld(true);const box=new THREE.Box3().setFromObject(root);box.getCenter(referenceCenter);const size=box.getSize(new THREE.Vector3());scale=3/Math.max(size.x,size.y,size.z);root.scale.setScalar(scale);root.position.copy(referenceCenter).multiplyScalar(-scale);scene.add(root);$('opacity').value=mode==='vascular'?22:100;$('opacityValue').value=$('opacity').value+'%';$('cut').checked=false;$('slice').disabled=true;$('slice').value=0;$('explode').value=0;setHome();updateAppearance();renderList();$('load').hidden=true;$('modelTitle').textContent=mode==='internal'?'HEART • INTERNAL ANATOMY':mode==='vascular'?'HEART • VASCULAR ANATOMY':'HEART WALL • TEACHING SCHEMATIC';$('dataset').innerHTML=mode==='internal'?'Human Reference Atlas / HuBMAP<br>Visible Human Male · CC BY 4.0':mode==='vascular'?'BodyParts3D / DBCLS<br>Adult male reference · CC BY 4.0':'Original schematic<br>Not to scale · Layers separated for teaching';$('modelnote').textContent=mode==='layers'?'Schematic wall sample. Thicknesses and spacing are exaggerated; the real layers follow the heart’s curved surface.':mode==='vascular'?'A separate reference heart. Colours distinguish structures. Long vessels are cropped to the heart region.':'Reference anatomy. Colours distinguish structures and do not represent natural tissue colours.';$('axes').hidden=mode==='layers';if(!linkApplied&&linkParams.get('part')){const linked=items.find(i=>i.name===linkParams.get('part'));if(linked){linkApplied=true;choose(linked);isolated=true;updateAppearance();focusSelected();}}}catch(e){if(token!==loadToken)return;delete cache[mode];$('load').textContent='The 3D model could not load. Check your connection and try again.';const b=document.createElement('button');b.textContent='Retry model';b.className='errorbutton';b.onclick=()=>loadModel(mode);$('load').append(b);console.error(e)}}
function renderList(){const q=$('search').value.toLowerCase();const visible=items.filter(i=>i.name.toLowerCase().includes(q));$('count').textContent=items.length;const groups=[...new Set(visible.map(i=>i.group))];$('structurelist').replaceChildren();if(!visible.length){$('structurelist').textContent='No matching structure in this view.';return}for(const cat of groups){const heading=document.createElement('div');heading.className='list-heading';heading.textContent=cat;$('structurelist').append(heading);for(const item of visible.filter(i=>i.group===cat)){const button=document.createElement('button');button.className='part'+(selected===item?' active':'');button.setAttribute('aria-pressed',String(selected===item));const dot=document.createElement('i');dot.style.background=item.colour;button.append(dot,document.createTextNode(item.name));button.onclick=()=>choose(item);$('structurelist').append(button)}}}
function choose(item){selected=item;const d=describe(item.name);$('category').textContent=d[0].toUpperCase();$('name').textContent=item.name;$('instruction').hidden=true;$('details').hidden=false;$('english').textContent=d[1];$('hausa').textContent=d[2];$('colour').style.background=item.colour;$('pin').textContent=item.name;$('pin').hidden=false;if(mode==='internal'&&['Valves','Internal supports'].includes(d[0])&&!isolated){$('opacity').value=16;$('opacityValue').value='16%'}updateAppearance();renderList()}
function updateAppearance(){const opacity=+$('opacity').value/100;const explode=+$('explode').value/100;cutPlane.constant=+$('slice').value/100*1.7;items.forEach(item=>item.meshes.forEach(m=>{m.visible=!isolated||item===selected;const wall=item.group==='Chambers'||item.group==='Heart wall';m.material.opacity=wall?(item===selected?Math.max(opacity,.65):opacity):1;m.material.transparent=m.material.opacity<1;m.material.depthWrite=m.material.opacity>=.98;m.material.emissive.set(item===selected?'#786c2c':'#000000');m.material.emissiveIntensity=item===selected?.25:0;m.material.clippingPlanes=$('cut').checked?[cutPlane]:[];m.material.needsUpdate=true;const c=m.userData.center.clone().add(m.userData.base).sub(referenceCenter);if(c.length()<.0001)c.set(0,0,1);c.normalize().multiplyScalar(explode*(mode==='layers'?.75:1.1)/scale);m.position.copy(m.userData.base).add(c)}));$('isolate').setAttribute('aria-pressed',String(isolated));$('isolate').textContent=isolated?'Restore surrounding structures':'Isolate this structure';}
function focusSelected(){if(!selected)return;root.updateMatrixWorld(true);const box=new THREE.Box3();selected.meshes.forEach(m=>box.expandByObject(m));const center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3());const direction=camera.position.clone().sub(controls.target).normalize();const distance=Math.max(.85,Math.max(size.x,size.y,size.z)*2.8);controls.target.copy(center);camera.position.copy(center).addScaledVector(direction,distance);controls.update()}
$('search').oninput=renderList;$('lang').onchange=()=>{document.body.classList.remove('en','ha');if($('lang').value!=='both')document.body.classList.add($('lang').value)};
try{setup();document.querySelectorAll('[data-model]').forEach(b=>b.onclick=()=>loadModel(b.dataset.model));$('opacity').oninput=()=>{$('opacityValue').value=$('opacity').value+'%';updateAppearance()};$('explode').oninput=updateAppearance;$('slice').oninput=updateAppearance;$('cut').onchange=()=>{$('slice').disabled=!$('cut').checked;updateAppearance()};$('isolate').onclick=()=>{if(!selected)return;isolated=!isolated;updateAppearance()};$('focus').onclick=focusSelected;$('showall').onclick=()=>{isolated=false;updateAppearance()};$('reset').onclick=()=>{isolated=false;$('cut').checked=false;$('slice').disabled=true;$('explode').value=0;$('opacity').value=mode==='vascular'?22:100;$('opacityValue').value=$('opacity').value+'%';controls.autoRotate=false;$('rotate').classList.remove('active');$('rotate').setAttribute('aria-pressed','false');updateAppearance();setHome()};$('front').onclick=()=>{controls.target.set(0,0,0);camera.position.set(0,.2,7)};$('back').onclick=()=>{controls.target.set(0,0,0);camera.position.set(0,.2,-7)};$('top').onclick=()=>{controls.target.set(0,0,0);camera.position.set(0,7,.01)};$('rotate').onclick=()=>{controls.autoRotate=!controls.autoRotate;$('rotate').classList.toggle('active',controls.autoRotate);$('rotate').setAttribute('aria-pressed',String(controls.autoRotate))};$('zoomIn').onclick=()=>{const d=camera.position.clone().sub(controls.target);d.multiplyScalar(.8);if(d.length()>=controls.minDistance)camera.position.copy(controls.target).add(d)};$('zoomOut').onclick=()=>{const d=camera.position.clone().sub(controls.target);d.multiplyScalar(1.25);if(d.length()<=controls.maxDistance)camera.position.copy(controls.target).add(d)};loadModel(['internal','vascular','layers'].includes(linkParams.get('model'))?linkParams.get('model'):'internal')}catch(e){$('load').textContent='Your browser could not start 3D graphics. Enable hardware acceleration or try another browser. The original lesson remains available above.';console.error(e)}
